# ---- phase 2 lessons (c11-c16) ----
L.append(dict(id='c11-union-find',title='Union-Find (Disjoint Sets)',used=['p13-redundant-connection','p35-accounts-merge'],scenes=[
 S('title',['This lesson is about union find, also called disjoint set union. It answers one question very fast: are these two things in the same group?'],title='Union-Find',sub='Who is in my group?'),
 S('analogy',['Picture a school where every club has one captain.','To ask whether two students are in the same club, you ask each of them: who is your captain? If the captains match, they are in the same club.','To merge two clubs, one captain simply agrees to report to the other captain.','That is the whole idea. Find means: follow the chain up to the captain. Union means: make one captain report to another.'],text='Every club has a captain. find(x) = walk up to your captain. union(a, b) = one captain starts reporting to the other.',icons=['find','union','captain']),
 S('graph',['Here are six people, each starting as their own captain.','We union one and two. Now one is the captain of two.','We union three and four, then two and three. The groups join into one big tree.','Five and six stay in their own small group, so find of five and find of one are different.'],title='Merging groups',nodes=[['1',140,140],['2',300,140],['3',460,140],['4',620,140],['5',300,320],['6',460,320]],edges=[[0,1],[2,3],[1,2],[4,5]],states=[dict(note='everyone is their own captain'),dict(he=[[0,1]],hl=[0,1],note='union(1,2)'),dict(he=[[0,1],[2,3],[1,2]],ok=[0,1,2,3],note='union(3,4), union(2,3) → one group'),dict(he=[[0,1],[2,3],[1,2],[4,5]],ok=[0,1,2,3],hl=[4,5],note='{5,6} is a different group')]),
 S('array',['In code, the whole structure is just one array called parent.','parent of i holds who i reports to. A captain points to itself.','Find follows parent pointers until it reaches someone who points to themself.','Path compression is a shortcut: on the way back, point every visited node straight at the captain, so the next find is one step.'],title='The parent array',states=[dict(a=[0,1,2,3,4,5],note='parent[i] = i: everyone is a root'),dict(a=[0,0,1,2,4,5],ptr={'x':3},note='find(3): 3 → 2 → 1 → 0'),dict(a=[0,0,0,0,4,5],ptr={'x':3},hl=[1,2,3],note='after path compression: all point at 0')]),
 S('bullets',['Here are the words you will hear.','A root, or representative, is the captain of a set.','Union by rank or size attaches the smaller tree under the bigger one, which keeps trees short.','With both tricks, each operation is almost constant time. The math name is inverse Ackermann, alpha of n, which is at most four for any real input.'],title='Jargon',items=['root / representative = the captain','union by rank/size = small tree under big tree','path compression = point straight at the root','cost ≈ O(α(n)) ≈ constant']),
 S('bullets',['Where does this show up?','Redundant Connection: an edge whose two ends already share a captain closes a cycle.','Accounts Merge: emails are the people, and sharing an account means union.','In systems: connected components in a network, grouping crash reports by shared stack frames, and Kruskal\'s minimum spanning tree.'],title='Where it is used',items=['Cycle detection in undirected graphs','Accounts merge / identity resolution','Network connectivity, Kruskal MST','Grouping related crash reports']),
 S('title',['Remember: find walks up to the captain, union links two captains, and the two tricks make it nearly free. Try Redundant Connection next.'],title='Recap',sub='parent[] • find • union • compression + rank'),
]))
L.append(dict(id='c12-tries',title='Tries (Prefix Trees)',used=['p14-trie','p30-word-search-ii'],scenes=[
 S('title',['This lesson covers tries, the tree built for words and prefixes. It powers autocomplete.'],title='Tries',sub='A tree of letters'),
 S('analogy',['Think of a giant filing cabinet for words.','The first drawer is chosen by the first letter, the folder inside by the second letter, and so on.','Words that start the same way share the same drawers. Car and cat share the drawers c and a.','A small flag on a folder says: a complete word ends here.'],text='A filing cabinet where each drawer is one letter. Words with the same start share drawers; a flag marks "a word ends here".',icons=['c','a','r / t','end flag']),
 S('tree',['Here is a trie holding the words a, at, and to, drawn as a tree of letter codes.','Searching for at means: from the root, take the a edge, then the t edge, then check the end flag.','If an edge is missing, the word is not there, and we stop immediately.','The cost depends only on the length of the word, not on how many words are stored.'],title='Walking edges letter by letter',tree=[0,1,20,None,20],states=[dict(hl=[0],note='root (labels: 1 = a, 20 = t)'),dict(ok=[0],hl=[1],note='take edge "a"'),dict(ok=[0,1],hl=[20],note='then "t" → end flag set → found'),dict(ok=[0,1,20],note='cost = O(word length)')]),
 S('bullets',['Some vocabulary.','A node usually stores up to twenty six child pointers, one per letter, or a small hash map when the alphabet is large.','Search asks whether a full word exists. StartsWith asks whether any word begins with a prefix.','For autocomplete, each node can also cache its top suggestions, so typing a prefix returns results instantly.'],title='Jargon',items=['children: array[26] or hash map','search(word) needs the end flag','startsWith(prefix) only needs the path','autocomplete: cache top-k per node']),
 S('grid',['Word Search Two combines a trie with a grid search.','Instead of searching for each word separately, we walk the grid once and follow trie edges as we go.','The moment the trie says no word starts like this, we turn back. That pruning is the whole speed up.'],title='Trie-guided grid search',states=[dict(g=[['o','a','a','n'],['e','t','a','e'],['i','h','k','r']],hl=[[0,0]],note='start "o": trie has o'),dict(g=[['o','a','a','n'],['e','t','a','e'],['i','h','k','r']],hl=[[0,0],[0,1],[1,1]],note='"oat" is still a prefix'),dict(g=[['o','a','a','n'],['e','t','a','e'],['i','h','k','r']],ok=[[0,0],[0,1],[1,1],[2,1]],note='"oath" found ✓')]),
 S('bullets',['Interview tips for tries.','Say why a hash set is not enough: it cannot answer prefix questions cheaply.','Mention memory: twenty six pointers per node adds up, so compressed tries or sorted arrays are used in production.','And for systems: IP routing tables use a binary trie for longest prefix match.'],title='Interview tips',items=['Hash set can\'t do prefix queries cheaply','Memory: 26 pointers/node → compressed (radix) tries','Longest-prefix match in IP routing','Clear found words to avoid duplicates']),
 S('title',['Tries trade memory for fast prefix lookups. Practice Implement Trie, then Word Search Two.'],title='Recap',sub='letters as edges • end flag • prefix pruning'),
]))
L.append(dict(id='c13-bit-tricks',title='Bit Manipulation Tricks',used=['p19-counting-bits','p41-n-queens-ii','p47-single-number','p48-reverse-bits','p62-buddy-allocator'],scenes=[
 S('title',['This lesson is about bit tricks. You already use them in driver code; here is how interviews use them.'],title='Bit Manipulation',sub='Light switches in a row'),
 S('analogy',['Think of an integer as a row of thirty two light switches.','Each switch is a bit: one is on, zero is off.','AND keeps a light on only if both rows have it on. OR turns it on if either does. XOR turns it on if exactly one does.','Shifting slides the whole row left or right, which is multiplying or dividing by two.'],text='An int is a row of 32 light switches. AND, OR, XOR combine two rows; shifts slide the row.',icons=['AND &','OR |','XOR ^','shift << >>']),
 S('array',['Let us look at the number twelve in binary: one one zero zero.','x and one tells you the lowest bit, so twelve is even.','x and minus x isolates the lowest set bit. For twelve that is four.','x and x minus one clears the lowest set bit. Twelve becomes eight. Repeat until zero to count the set bits.'],title='Three tricks on x = 12',states=[dict(a=[1,1,0,0],note='12 = 1100₂'),dict(a=[0,1,0,0],hl=[1],note='x & −x = 0100₂ = 4 (lowest set bit)'),dict(a=[1,0,0,0],hl=[0],note='x & (x − 1) = 1000₂ = 8 (lowest bit cleared)')]),
 S('bullets',['XOR has two magic rules.','Any number XOR itself is zero. Any number XOR zero is itself.','So in Single Number, XOR everything together, and the pairs cancel out, leaving the lonely number.','RAID five storage uses the same rule: the parity block is the XOR of all data blocks, so any one lost block can be rebuilt.'],title='XOR cancels pairs',items=['a ^ a = 0','a ^ 0 = a','XOR all → pairs vanish → single remains','RAID-5 parity rebuilds a lost disk']),
 S('bullets',['Bitmasks also store sets of small integers.','Bit i set means item i is in the set. Union is OR, intersection is AND.','N Queens keeps three masks: taken columns and the two diagonal directions, so checking a square is one AND.','The buddy allocator finds a block\'s partner with offset XOR size, flipping exactly one bit.'],title='Bitmasks as sets',items=['set i: mask |= 1 << i','test i: mask & (1 << i)','N-Queens: cols | diag1 | diag2','buddy = offset ^ size']),
 S('bullets',['Watch out for language gotchas.','Java has no unsigned int, so use the triple right shift or a long.','In C plus plus, shifting a signed negative number or shifting by thirty two or more is undefined behavior.','C sharp has real unsigned types, uint and ulong, which make this simpler.'],title='Gotchas',items=['Java: use >>> and long for unsigned','C++: no shifting by ≥ width, careful with signed','C#: uint / ulong exist','Name masks with constants, comment each bit']),
 S('title',['Bits are cheap and fast. Practice Single Number, Counting Bits and Reverse Bits.'],title='Recap',sub='& | ^ << >> • x & −x • x & (x−1) • masks as sets'),
]))
L.append(dict(id='c14-binary-search',title='Binary Search (and Searching the Answer)',used=['p16-rotated-search','p38-median-two-sorted','p39-koko-bananas','p53-search-2d-matrix','p43-lis'],scenes=[
 S('title',['This lesson covers binary search, including the powerful trick of binary searching the answer itself.'],title='Binary Search',sub='Halve the haystack'),
 S('analogy',['Think of guessing a number between one and a hundred, where a friend says higher or lower.','A smart guesser always picks the middle. Each answer throws away half of the remaining numbers.','After only seven guesses you have found any number between one and a hundred.','That halving is why binary search costs log n.'],text='Guess a number 1–100 with "higher/lower" hints: always guess the middle and discard half each time.',icons=['guess middle','discard half','log₂ n steps']),
 S('array',['Here is a sorted array, and we search for the value nine.','Low is zero, high is seven, so mid is three, holding seven. Seven is smaller than nine, so search the right half.','Now mid is five, holding eleven. Too big, so search the left part.','Mid is four, holding nine. Found in three steps.'],title='Classic binary search',states=[dict(a=[1,3,5,7,9,11,13,15],ptr={'lo':0,'mid':3,'hi':7},note='7 < 9 → lo = mid + 1'),dict(a=[1,3,5,7,9,11,13,15],ptr={'lo':4,'mid':5,'hi':7},note='11 > 9 → hi = mid − 1'),dict(a=[1,3,5,7,9,11,13,15],ptr={'lo':4,'mid':4,'hi':4},hl=[4],note='found 9')]),
 S('array',['Now the more powerful idea: searching for an answer.','In Koko Eating Bananas, we want the slowest eating speed that still finishes in time.','If a speed works, every faster speed also works. The answers look like no, no, no, yes, yes, yes.','Binary search finds the first yes. Each check costs one pass over the piles.'],title='Binary search on the answer',states=[dict(a=['no','no','no','yes','yes','yes','yes','yes'],ptr={'lo':0,'hi':7},note='speeds 1..8: feasible?'),dict(a=['no','no','no','yes','yes','yes','yes','yes'],ptr={'mid':3},hl=[3],note='mid works → keep searching left'),dict(a=['no','no','no','yes','yes','yes','yes','yes'],ptr={'ans':3},ok=[3],note='first "yes" = minimum speed')]),
 S('bullets',['A little vocabulary.','The invariant is the promise your loop keeps, for example: the answer is always between low and high.','Lower bound finds the first element greater than or equal to x. Upper bound finds the first element greater than x.','A monotonic predicate is a yes or no test that flips only once. If you can find one, you can binary search.'],title='Jargon',items=['invariant: answer stays inside [lo, hi]','lower_bound: first ≥ x','upper_bound: first > x','monotonic predicate → searchable']),
 S('bullets',['The classic bugs.','Overflow in low plus high, so write low plus high minus low divided by two.','Infinite loops when low equals mid; pick one loop style and stick to it.','And off by one at the edges. Test with arrays of size zero, one and two.'],title='Bugs to avoid',items=['mid = lo + (hi − lo) / 2','One loop template: while (lo < hi) with hi = mid','Test n = 0, 1, 2','Know which side you discard and why']),
 S('title',['If the data is sorted, or the answer is monotonic, think binary search. Try Koko, then Median of Two Sorted Arrays.'],title='Recap',sub='halve • invariant • search the answer'),
]))
L.append(dict(id='c15-backtracking',title='Backtracking',used=['p17-subsets','p40-permutations','p41-n-queens-ii','p30-word-search-ii'],scenes=[
 S('title',['This lesson covers backtracking: trying choices, and undoing them when they do not work.'],title='Backtracking',sub='Choose, explore, un-choose'),
 S('analogy',['Picture walking through a maze with a ball of string.','At each fork you pick a path and unroll string behind you.','If you hit a dead end, you walk back along the string to the last fork and try the next path.','Rolling the string back up is the undo step. That is backtracking.'],text='A maze with a ball of string: pick a path, and at a dead end roll the string back to the last fork and try another.',icons=['choose','explore','dead end','undo']),
 S('callstack',['Here is permutations of one, two, three as a call stack.','The first call chooses one. It calls deeper, which chooses two, then three. A full row is recorded.','Then the deepest frame returns, and two is un-chosen so three can be tried in its place.','Each frame on the stack is one decision. The depth of the stack is the length of the path.'],title='The decision stack',states=[dict(frames=['dfs([])'],note='start'),dict(frames=['dfs([])','dfs([1])','dfs([1,2])','dfs([1,2,3]) ✓'],note='record [1,2,3]'),dict(frames=['dfs([])','dfs([1])','dfs([1,3])'],note='un-choose 2, try 3'),dict(frames=['dfs([])','dfs([1])','dfs([1,3])','dfs([1,3,2]) ✓'],note='record [1,3,2]')]),
 S('bullets',['The template is always the same three lines.','Choose: add an option to the current path and mark it used.','Explore: recurse to make the next decision.','Un-choose: remove it again, so the path is clean for the next option.','And when the path is complete, save a COPY of it, not the path itself.'],title='The template',items=['choose: path.push(x); used[x] = true','explore: dfs(...)','un-choose: path.pop(); used[x] = false','record a COPY at the leaf']),
 S('bullets',['Pruning is what makes backtracking fast enough.','Pruning means refusing to go down a path that cannot succeed.','N Queens prunes any square already attacked. Word Search Two prunes any letters that are not a prefix of a word.','Good pruning can turn hours into milliseconds, even though the worst case stays exponential.'],title='Pruning',items=['Skip choices that break a rule','N-Queens: attacked squares','Word Search II: dead prefixes','Worst case still exponential: say so']),
 S('bullets',['Interview tips.','Draw the decision tree for a tiny input before coding.','State the complexity honestly: subsets is two to the n, permutations is n factorial.','For duplicates in the input, sort first and skip equal neighbors at the same depth.'],title='Interview tips',items=['Draw the tree for n = 3','Subsets O(n·2ⁿ), permutations O(n·n!)','Duplicates: sort + skip equal siblings','Watch recursion depth limits']),
 S('title',['Choose, explore, un-choose, and prune early. Try Subsets, Permutations and N Queens.'],title='Recap',sub='decision tree • template • pruning'),
]))
L.append(dict(id='c16-intervals',title='Intervals & Sweep Lines',used=['p15-merge-dma','p36-meeting-rooms-ii','p37-insert-interval','p63-my-calendar'],scenes=[
 S('title',['This lesson covers intervals: meetings, reservations, memory ranges and time windows.'],title='Intervals & Sweep Lines',sub='Bars on a timeline'),
 S('analogy',['Think of a shared calendar for a meeting room.','Each meeting is a bar with a start and an end.','Two bars overlap if each one starts before the other ends.','Most interval problems become easy once the bars are sorted by start time, because then you only compare neighbors.'],text='Meetings are bars on a timeline. Two bars overlap when each starts before the other ends. Sort by start, then compare neighbours.',icons=['start','end','overlap?','sort']),
 S('array',['Merge intervals: sort by start, then sweep left to right.','The first bar is one to three. The next, two to six, starts before three ends, so merge them into one to six.','Eight to ten starts after six, so it begins a new group.','One pass after sorting: n log n total.'],title='Merging overlaps',states=[dict(a=['[1,3]','[2,6]','[8,10]','[15,18]'],ptr={'i':0},note='sorted by start'),dict(a=['[1,6]','[8,10]','[15,18]'],hl=[0],note='[1,3] + [2,6] → [1,6]'),dict(a=['[1,6]','[8,10]','[15,18]'],ok=[0,1,2],note='no more overlaps')]),
 S('heap',['How many rooms do we need at the busiest moment?','Sort meetings by start. Keep a min heap of end times for rooms in use.','When a new meeting starts after the earliest end on top of the heap, that room is free: pop it.','Push the new end time. The biggest the heap ever gets is the number of rooms.'],title='Meeting Rooms II with a min-heap',states=[dict(a=[30],note='[0,30) → heap {30}'),dict(a=[10,30],note='[5,10): 30 > 5 → new room'),dict(a=[20,30],hl=[0],note='[15,20): 10 ≤ 15 → reuse → 2 rooms')]),
 S('bullets',['Vocabulary.','Half open, written with a square bracket and a round bracket, means the end time is not included. A meeting ending at five and one starting at five do not clash.','A sweep line walks through all start and end events in time order, adding one at a start and subtracting one at an end.','An interval map, like a balanced tree keyed by start, answers can I book this in log n time.'],title='Jargon',items=['[start, end) = half-open interval','sweep line: +1 at start, −1 at end','interval map: ordered tree by start','overlap test: a.s < b.e && b.s < a.e']),
 S('bullets',['Systems uses.','GPU cluster schedulers reserve nodes over time windows.','Memory allocators merge adjacent free ranges, just like merging DMA regions.','And monitoring systems compute busy time from start and stop events.'],title='In systems',items=['GPU/job reservations (calendar)','Free-range coalescing in allocators','Merging DMA regions','Busy-time from start/stop events']),
 S('title',['Sort by start, compare neighbors, and use a heap or sweep line for peaks. Try Merge Intervals and Meeting Rooms Two.'],title='Recap',sub='sort • merge • heap of ends • sweep'),
]))
